-- Custom migration: Add client statistics function
-- This file should be run manually or via custom script
-- Generated: Manual (functions cannot be auto-generated by drizzle-kit)
-- Location: drizzle/migrations/ (same as auto-generated migrations)

CREATE OR REPLACE FUNCTION get_client_stats(client_uuid UUID, org_uuid UUID)
RETURNS JSON AS $$
DECLARE
    result JSON;
BEGIN
    SELECT json_build_object(
        'totalInvoiced', COALESCE(SUM(CAST(i.total AS DECIMAL)), 0),
        'totalPaid', COALESCE(SUM(CAST(p.amount AS DECIMAL)), 0),
        'totalUnpaid', COALESCE(SUM(CAST(i.total AS DECIMAL)), 0) - COALESCE(SUM(CAST(p.amount AS DECIMAL)), 0),
        'invoiceCount', COUNT(DISTINCT i.id),
        'paidInvoiceCount', COUNT(DISTINCT CASE 
            WHEN COALESCE(invoice_payments.total_paid, 0) >= CAST(i.total AS DECIMAL) 
            THEN i.id 
        END),
        'unpaidInvoiceCount', COUNT(DISTINCT i.id) - COUNT(DISTINCT CASE 
            WHEN COALESCE(invoice_payments.total_paid, 0) >= CAST(i.total AS DECIMAL) 
            THEN i.id 
        END),
        'paidPercentage', CASE 
            WHEN COUNT(DISTINCT i.id) > 0 
            THEN (COUNT(DISTINCT CASE 
                WHEN COALESCE(invoice_payments.total_paid, 0) >= CAST(i.total AS DECIMAL) 
                THEN i.id 
            END) * 100.0) / COUNT(DISTINCT i.id)
            ELSE 0 
        END,
        'averageInvoiceAmount', CASE 
            WHEN COUNT(DISTINCT i.id) > 0 
            THEN COALESCE(SUM(CAST(i.total AS DECIMAL)), 0) / COUNT(DISTINCT i.id)
            ELSE 0 
        END
    ) INTO result
    FROM invoices i
    LEFT JOIN payments p ON i.id = p.invoice_id
    LEFT JOIN (
        SELECT 
            invoice_id, 
            SUM(CAST(amount AS DECIMAL)) as total_paid
        FROM payments 
        GROUP BY invoice_id
    ) invoice_payments ON i.id = invoice_payments.invoice_id
    WHERE i.client_id = client_uuid 
    AND i.organization_id = org_uuid;
    
    RETURN result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;